import { defineComponent } from 'vue';
import { PrizeLeagueManager } from '../../../services/prize-league/prize-league-manager';
import { getPrizeLeagueManager } from '../prize-league-utils';
import { inversifyContainer } from '../../../inversify/container';
import { getEndpoints } from '../../../endpoints/uk-endpoints';

export default defineComponent({
    name: 'BottomPanel',
    props: {
        tournamentId: {
            type: String,
            required: true
        }
    },
    computed: {
        prizeLeagueManager(): PrizeLeagueManager {
            return getPrizeLeagueManager();
        },
        translations() {
            return inversifyContainer.strings.prizeLeague;
        },
        currentlyViewedTournament() {
            return this.prizeLeagueManager.currentlyViewedTournament.value;
        },
        activeTournament() {
            return this.prizeLeagueManager.activeTournament.value;
        },
        isActiveTournament(): boolean {
            return this.currentlyViewedTournament?.tournamentId === this.activeTournament?.tournamentId;
        },
        userData() {
            return this.prizeLeagueManager.userData.value;
        }
    },
    emits: ['change-panel'],
    methods: {
        async onOptInClicked() {
            if (this.tournamentId) {
                const success = await this.prizeLeagueManager.optInToTournament(this.tournamentId);
            
                if (!success) return;

                const tournament = this.prizeLeagueManager.tournamentList.value.find(t => t.tournamentId === this.tournamentId);
                if (tournament && tournament.tournamentStatus === 'Active') {
                    this.$emit('change-panel', 'leaderboard', this.tournamentId);
                }
            }
        },
        termsAndConditionsClicked() {
            inversifyContainer.frameConnection.operator.onUserActionRequired({ type: 'navigation', data: { type: 'url', location: getEndpoints().prizeLeagueTandCs } });
        }
    }
});
